CREATE TABLE "Crypto" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, -- รหัสแถว (Auto-increment)
  "symbol" varchar NOT NULL,                                -- ชื่อย่อเหรียญ (เช่น BTC, ETH)
  "last_usd" decimal,                                       -- ราคาล่าสุด (ดอลลาร์สหรัฐ)
  "last_thb" decimal,                                       -- ราคาล่าสุด (บาทไทย - คำนวณในขั้น Transform)
  "last_btc" decimal,                                       -- มูลค่าเทียบกับ BTC
  "lowest_usd" decimal,                                     -- ราคาต่ำสุดในรอบ 24 ชม. (USD)
  "highest_usd" decimal,                                    -- ราคาสูงสุดในรอบ 24 ชม. (USD)
  "daily_change_percentage" decimal,                        -- เปอร์เซ็นต์การเปลี่ยนแปลงใน 24 ชม.
  "source_exchange" varchar,                                -- กระดานเทรดต้นทาง (เช่น Binance)
  "extracted_at" timestamp                                  -- เวลาที่ Pipeline ดึงข้อมูลนี้เข้ามา
);

-- สร้าง Unique Index เพื่อป้องกันการบันทึกข้อมูลซ้ำ ณ เวลาอัปเดตเดียวกัน
CREATE UNIQUE INDEX idx_crypto_symbol_time ON "Crypto" ("symbol", "source_timestamp");

-- คำอธิบายระดับตาราง
COMMENT ON TABLE "Crypto" IS 'ตารางเก็บข้อมูลราคาเหรียญคริปโตที่ผ่านการแปลงค่าเงินบาทแล้ว';

-- คำอธิบายระดับคอลัมน์
COMMENT ON COLUMN "Crypto"."id" IS 'รหัสแถว (Auto-increment)';
COMMENT ON COLUMN "Crypto"."symbol" IS 'ชื่อย่อเหรียญ (เช่น BTC, ETH)';
COMMENT ON COLUMN "Crypto"."last_usd" IS 'ราคาล่าสุด (ดอลลาร์สหรัฐ)';
COMMENT ON COLUMN "Crypto"."last_thb" IS 'ราคาล่าสุด (บาทไทย - คำนวณในขั้น Transform)';
COMMENT ON COLUMN "Crypto"."last_btc" IS 'มูลค่าเทียบกับ BTC';
COMMENT ON COLUMN "Crypto"."lowest_usd" IS 'ราคาต่ำสุดในรอบ 24 ชม. (USD)';
COMMENT ON COLUMN "Crypto"."highest_usd" IS 'ราคาสูงสุดในรอบ 24 ชม. (USD)';
COMMENT ON COLUMN "Crypto"."daily_change_percentage" IS 'เปอร์เซ็นต์การเปลี่ยนแปลงใน 24 ชม.';
COMMENT ON COLUMN "Crypto"."source_exchange" IS 'กระดานเทรดต้นทาง (เช่น Binance)';
COMMENT ON COLUMN "Crypto"."source_timestamp" IS 'เวลาอัปเดตราคาจากแหล่งข้อมูล';
COMMENT ON COLUMN "Crypto"."extracted_at" IS 'เวลาที่ Pipeline ดึงข้อมูลนี้เข้ามา';